let mudou = 0;
let jaEstava = 0;

for (const alvo of arquivos) {
  const novo = Buffer.from(alvo.conteudo, "base64").toString("utf8");

  if (existsSync(alvo.caminho)) {
    const atual = readFileSync(alvo.caminho, "utf8");
    const usaCRLF = atual.includes("\r\n");
    const saida = usaCRLF
      ? novo.replace(/\r\n/g, "\n").replace(/\n/g, "\r\n")
      : novo.replace(/\r\n/g, "\n");

    if (atual === saida) {
      jaEstava += 1;
      console.log("  [pulou] " + alvo.rotulo + " (ja estava aplicada)");
      continue;
    }

    writeFileSync(alvo.caminho, saida, "utf8");
  } else {
    mkdirSync(dirname(alvo.caminho), { recursive: true });
    writeFileSync(alvo.caminho, novo, "utf8");
  }

  mudou += 1;
  console.log("  [ok]    " + alvo.rotulo);
}

// ---- migration (arquivo novo dentro de pasta nova) ----
const PASTA_MIGRATION = "prisma/migrations/20260911140000_pacote_cliente";
const CAMINHO_MIGRATION = PASTA_MIGRATION + "/migration.sql";
const MIGRATION_B64 = "";
const migrationConteudo = Buffer.from(MIGRATION_B64, "base64").toString("utf8");

if (existsSync(CAMINHO_MIGRATION)) {
  const atualMig = readFileSync(CAMINHO_MIGRATION, "utf8");
  if (atualMig.trim() === migrationConteudo.trim()) {
    jaEstava += 1;
    console.log("  [pulou] migration do banco (ja estava aplicada)");
  } else {
    mudou += 1;
    writeFileSync(CAMINHO_MIGRATION, migrationConteudo, "utf8");
    console.log("  [ok]    migration do banco atualizada");
  }
} else {
  mkdirSync(PASTA_MIGRATION, { recursive: true });
  writeFileSync(CAMINHO_MIGRATION, migrationConteudo, "utf8");
  mudou += 1;
  console.log("  [ok]    migration do banco criada");
}

console.log(
  "\nPronto! " + mudou + " alteracao(oes) aplicada(s)" +
    (jaEstava > 0 ? ", " + jaEstava + " ja estava(m) no lugar" : "") + ".\n",
);
console.log("A aba nova fica na ficha da cliente: Pacotes\n");
console.log("Agora rode:  npm run build\n");
console.log("(o build ja roda 'prisma migrate deploy' sozinho, que aplica a tabela nova no banco)\n");
